<?php
require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/../includes/functions.php';require_once __DIR__.'/../includes/csrf.php';require_role(['Faculty']);
$user=current_user();$error=$success=null;
$faculty=$pdo->prepare('SELECT * FROM faculty WHERE user_id=?');$faculty->execute([$user['id']]);$faculty=$faculty->fetch();
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$clearanceId=filter_input(INPUT_POST,'clearance_id',FILTER_VALIDATE_INT);$action=$_POST['action']??'';$remarks=trim($_POST['remarks']??'');
 $dc=$pdo->prepare('SELECT dc.*,cr.student_id,cr.status request_status,u.id student_user_id FROM department_clearances dc JOIN clearance_requests cr ON cr.id=dc.request_id JOIN students s ON s.id=cr.student_id JOIN users u ON u.id=s.user_id WHERE dc.id=? AND dc.department_id=?');
 $dc->execute([$clearanceId,$faculty['department_id']]);$row=$dc->fetch();
 if(!$row||$row['request_status']==='Approved'){$error='Clearance is not available for verification.';}
 elseif(!in_array($action,['Approved','Rejected'],true)||($action==='Rejected'&&$remarks==='')){$error='A rejection reason is required.';}
 else{try{$pdo->beginTransaction();$pdo->prepare('UPDATE department_clearances SET status=?,remarks=?,faculty_user_id=?,updated_at=NOW() WHERE id=?')->execute([$action,$remarks,$user['id'],$clearanceId]);$pdo->prepare('INSERT INTO approvals(request_id,approver_user_id,role,department_id,status,remarks) VALUES(?,?,?,?,?,?)')->execute([$row['request_id'],$user['id'],'Faculty',$faculty['department_id'],$action,$remarks]);
 if($action==='Approved'){notify($pdo,(int)$row['student_user_id'],'Department clearance approved','The '.$pdo->query('SELECT name FROM departments WHERE id='.((int)$faculty['department_id']))->fetchColumn().' department has approved your clearance.',base_url().'/student/clearance_status.php');}else{notify($pdo,(int)$row['student_user_id'],'Department clearance rejected','Your clearance was rejected. Reason: '.$remarks,base_url().'/student/clearance_status.php');$pdo->prepare('UPDATE clearance_requests SET status=\'Rejected\' WHERE id=?')->execute([$row['request_id']]);}
 audit_log($pdo,(int)$user['id'],'Faculty',$action.' department clearance',$clearanceId,$remarks);$pdo->commit();$success='Clearance '.($action==='Approved'?'approved':'rejected').' successfully.';}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error='Unable to update clearance.';}}
}
$st=$pdo->prepare('SELECT dc.*,d.name department_name,cr.id request_id,cr.semester,u.name student_name,s.usn FROM department_clearances dc JOIN clearance_requests cr ON cr.id=dc.request_id JOIN students s ON s.id=cr.student_id JOIN users u ON u.id=s.user_id JOIN departments d ON d.id=dc.department_id WHERE dc.department_id=? AND dc.status=\'Pending\' ORDER BY cr.submitted_at DESC');$st->execute([$faculty['department_id']]);$rows=$st->fetchAll();
$pageTitle='Pending Requests | CLEARX';require_once __DIR__.'/../includes/header.php';
?><div class="app-layout"><?php require_once __DIR__.'/../includes/sidebar.php';?><main class="app-main"><header class="topbar"><button class="menu-toggle"><i class="fa-solid fa-bars"></i></button><div class="topbar-user"><b><?=e($user['name'])?></b><span>Faculty</span></div><div class="avatar"><?=e(strtoupper(substr($user['name'],0,2)))?></div></header><div class="content"><div class="page-header"><div><p>FACULTY WORKSPACE</p><h1>Pending Department Requests</h1></div></div><?php if($error):?><div class="alert alert-error"><?=e($error)?></div><?php endif;if($success):?><div class="alert alert-success"><?=e($success)?></div><?php endif;?><section class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Student</th><th>USN</th><th>Semester</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['student_name'])?></td><td><?=e($r['usn'])?></td><td><?=e($r['semester'])?></td><td><details><summary class="action-btn">Review</summary><form class="inline-form" method="post" style="display:grid;margin-top:8px"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="clearance_id" value="<?=(int)$r['id']?>"><textarea name="remarks" placeholder="Remarks (required for rejection)"></textarea><select name="action"><option value="Approved">Approve</option><option value="Rejected">Reject</option></select><button class="action-btn approve" type="submit">Submit</button></form></details></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="4">No pending requests.</td></tr><?php endif;?></tbody></table></div></section></div><?php require_once __DIR__.'/../includes/footer.php';?></main></div>
